import {writingTasks,writingCopy} from './writing-table-content.mjs';
import * as core from './writing-table-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=s=>`<p data-writing-read>${esc(s)}</p>`;
const button=(action,label,disabled=false)=>`<button type='button' data-writing-action='${action}'${disabled?' disabled':''}>${esc(label)}</button>`;
const title=s=>`<h2 id='writing-task-title' tabindex='-1' data-writing-read>${esc(s)}</h2>`;
let views=new WeakMap();
function local(state,owner){let v=views.get(state),id=state.writingDesk?.currentId||'';if(!v||v.owner!==owner){v={owner,id,selected:'',bench:'paragraphs',panels:[]};views.set(state,v);}if(v.id!==id){v.id=id;v.selected='';v.panels=[];}return v;}
function preview(s,w,label='Your page'){
 return `<section class='wt-page-preview'><h3>${esc(label)}</h3>${core.writingPreview(s,w).map(block=>`<div>${block.heading?`<h4 data-writing-read>${esc(block.heading)}</h4>`:''}${p(block.text||'No strips here yet.')}</div>`).join('')}</section>`;
}
function snapshot(s,k,label){return `<section class='wt-kept'><h3>${esc(label)}</h3>${core.validWritingSnapshot(s,k)?`${p(k.check?'Practice with this draft':'Not checked in this version')}${preview(s,k.work,'Kept page')}`:'<p>This earlier version stays in your Notes download, but cannot be read here.</p>'}</section>`;}
function controls(r,v){
 const s=r.source,w=r.work;
 if(s.kind==='sort')return `<div class='wt-sorting'><div class='wt-move-tools' tabindex='-1' id='writing-move-tools'><p data-writing-selected>${v.selected?'Moving: '+esc(s.parts.find(x=>x.id===v.selected)?.text):'Choose a strip first.'}</p><div class='wt-destinations'>${s.choices.map(h=>`<button type='button' data-writing-destination='${esc(h.id)}'${!v.selected?' disabled':''}>Put under ${esc(h.text)}</button>`).join('')}${button('put-back','Put back',!v.selected)}</div></div><div class='wt-strip-bank' aria-label='Sentence strips'>${s.parts.map((x,i)=>`<button type='button' class='wt-strip' data-writing-strip='${esc(x.id)}' aria-pressed='${v.selected===x.id}'><span>${i+1}</span><span>${esc(x.text)}<small>${esc(s.choices.find(h=>h.id===w.placements[x.id])?.text||'Waiting strip')}</small></span></button>`).join('')}</div></div>`;
 if(s.kind==='order')return `<ol class='wt-order'>${w.order.map((id,i)=>{const x=s.parts.find(x=>x.id===id);return `<li><p data-writing-read>${esc(x.text)}</p><div><button type='button' data-writing-move='${esc(id)}' data-writing-direction='-1'${i===0?' disabled':''} aria-label='Move earlier, paragraph ${i+1}'>Move earlier</button><button type='button' data-writing-move='${esc(id)}' data-writing-direction='1'${i===w.order.length-1?' disabled':''} aria-label='Move later, paragraph ${i+1}'>Move later</button></div></li>`;}).join('')}</ol>`;
 if(s.kind==='break')return `<div class='wt-breaks'>${s.parts.map((x,i)=>`${i?`<button type='button' data-writing-boundary='${esc(x.id)}' aria-pressed='${w.boundary===x.id}'>Start a paragraph here, before sentence ${i+1}</button>`:''}${p(x.text)}`).join('')}</div>`;
 return `<div class='wt-choices'>${s.choices.map(x=>`<button type='button' data-writing-choice='${esc(x.id)}' aria-pressed='${w.choice===x.id}'>${esc(x.text)}</button>`).join('')}</div>`;
}
function feedback(r){const last=r.checks.at(-1);if(!last)return '';return `<aside class='wt-feedback' id='writing-feedback' tabindex='-1'><h3>Last check</h3>${!core.sameWritingWork(last.work,r.work)?p('Checked before your last change'):''}${r.source.kind==='sort'&&last.outcome!=='fit'&&last.feedback.length>1?`${p(last.outcome==='incomplete'?writingCopy.incomplete:'Compare each strip with its heading.')}<details data-writing-strip-notes><summary>Look at the strip notes</summary>${last.feedback.map(p).join('')}</details>`:last.feedback.map(p).join('')}<small>Practice with this draft</small></aside>`;}
function shelf(state,v){const view=core.writingView(state);return `<details data-writing-panel='shelf'${v.panels.includes('shelf')?' open':''}><summary>Choose a draft</summary><div class='wt-benches'>${[['paragraphs','Paragraph Sort'],['linking','The Linking Word']].map(([id,label])=>`<button type='button' data-writing-bench='${id}' aria-pressed='${v.bench===id}'>${label}</button>`).join('')}</div><div class='wt-shelf'>${writingTasks.filter(x=>x.bench===v.bench).map(x=>`<button type='button' data-writing-open='${x.id}' aria-pressed='${state.writingDesk?.currentId===x.id}'>${esc(core.validWritingRecord(state.writingDesk?.records?.[x.id])?state.writingDesk.records[x.id].source.title:x.title)}</button>`).join('')}</div>${view.records.filter(x=>!writingTasks.some(t=>t.id===x.id)||!x.readable).map(x=>x.readable?`<button type='button' data-writing-open='${esc(x.id)}'>${esc(x.title)}</button>`:`<p>${esc(x.id)} is kept unchanged in your Notes download.</p>`).join('')}<p>Every draft stays open. Earlier work waits while you try another.</p></details>`;}
export function writingEntry(){return `<aside class='writing-entry'><h2>The Writing Table</h2><p>The librarian needs a page visitors can use. Arrange paper strips and help a reader follow the report.</p><a href='#desk/writing'>Try the Writing Table</a></aside>`;}
export function writingPage(state,owner=''){
 const view=core.writingView(state),r=view.record,v=local(state,owner);
 const heading=`<header class='wt-heading'><a href='#desk'><span aria-hidden='true'>←</span> Keeper’s Desk</a><h1>The Writing Table</h1><a href='#post/letters'>Letters for a reader</a></header>`;
 if(view.status==='unsupported')return `<section data-writing-root class='wt-room'>${heading}<p>This writing notebook needs another version of the game. It stays in your Notes download. Other places are open.</p><a href='#notes'>Download your Notes</a></section>`;
 const s=r?.source;
 return `<section data-writing-root class='wt-room'>${heading}<p class='wt-fiction'>A story from Willowbank</p>${!r?`<div class='wt-arrival'>${title('A page for the visitors')}${p(writingCopy.intro)}<div class='wt-paper-stack' aria-hidden='true'><span>Opening times</span><span>Finding the bakery</span><span>What’s for sale</span></div>${button('start','Start the bakery draft')}${hearButton(writingCopy.intro,'Hear the invitation')}</div>`:`<div class='wt-reader'>${p(s.reader)}${view.familiar?'<small>A draft you have seen</small>':''}</div><article class='wt-work'>${title(s.title)}${p(s.prompt)}${s.steps?`<ol class='wt-guided'>${s.steps.map(x=>`<li data-writing-read>${esc(x)}</li>`).join('')}</ol>`:''}${s.kind==='choice'?`<div class='wt-source'>${s.parts.map((x,i)=>p(s.numbered===true?`${i+1}. ${x.text}`:x.text)).join('')}</div>`:''}${s.changes?`<p class='wt-changes' data-writing-read>What changes: ${esc(s.changes)}</p>`:''}${controls(r,v)}<div class='wt-actions'>${button('check','Check this draft')}${button('keep','Keep this version')}${button('next','Next draft')}${hearButton('','Hear this task')}</div>${preview(s,r.work)}${feedback(r)}</article>`}<p id='writing-status' role='status' tabindex='-1' aria-live='polite'></p>${r?`<details data-writing-panel='teaching'${v.panels.includes('teaching')?' open':''}><summary>How writing works</summary>${s.teach.map(p).join('')}</details><details data-writing-panel='help'${v.panels.includes('help')?' open':''}><summary>Help and a separate example</summary>${button('hint','A hint')}${button('example','Try a separate example')}${button('together',r.help.together?'Reading together':'Read together')}${r.help.hint?p(s.hint):''}${r.help.example?p(s.example):''}</details><details data-writing-panel='versions'${v.panels.includes('versions')?' open':''}><summary>Kept versions</summary><div class='wt-versions'>${own(r,'firstKept')?snapshot(s,r.firstKept,'First kept version'):p('Keep any version, including an unfinished one.')}${own(r,'latestKept')?snapshot(s,r.latestKept,'Latest kept version'):''}</div></details>${p(writingCopy.invitation)}`:''}${shelf(state,v)}<details data-writing-panel='grownup'${v.panels.includes('grownup')?' open':''}><summary>For grown-ups</summary>${p(writingCopy.grownup)}<a href='#notes'>Notes and downloads</a></details></section>`;
}
const own=(x,k)=>Object.hasOwn(x,k);
export function writingNotes(state){
 if(!own(state,'writingDesk'))return '';const view=core.writingView(state);let raw;try{raw=JSON.stringify(state.writingDesk,null,2);}catch{raw='Original writing notebook remains in the full Notes download.';}
 return `<details class='panel'><summary>Writing Table: supplied drafts and kept versions</summary><p>${esc(writingCopy.grownup)}</p>${view.records.map(x=>{const r=state.writingDesk.records[x.id];return `<section><h3>${esc(x.title||x.id)}</h3>${x.readable?`${preview(r.source,r.work,'Current page')}${own(r,'firstKept')?snapshot(r.source,r.firstKept,'First kept version'):''}${own(r,'latestKept')?snapshot(r.source,r.latestKept,'Latest kept version'):''}`:'<p>Earlier unreadable work is retained unchanged.</p>'}</section>`;}).join('')}<details><summary>Full retained source and practice checks</summary><pre>${esc(raw)}</pre></details><a href='#desk/writing'>Return to the Writing Table</a></details>`;
}
const errors={unavailable:'This earlier draft cannot be changed here. It is still in your Notes download. Try another draft.',full:'There is no room for another draft in this writing notebook. Your earlier work is still here. Download your Notes.',unexportable:'This change could not be kept. Your earlier draft is still here. Download your Notes.',selection:'Choose an available draft.',material:'Choose a part of this draft.','kept-unavailable':'An earlier kept version cannot be read here. It stays unchanged. Your current draft is still editable; download your Notes.'};
export function bindWriting(state,ctx={}){
 const root=document.querySelector('[data-writing-root]');if(!root)return;
 const owner=ctx.explorerId?.()??'',v=local(state,owner),current=state.writingDesk?.currentId;let ownedRoot=state.writingDesk;
 const owned=()=>root.isConnected&&document.querySelector('[data-writing-root]')===root&&location.hash==='#desk/writing'&&(!ctx.notebook||ctx.notebook()===state)&&(ctx.explorerId?.()??'')===owner&&(!ctx.isActive||ctx.isActive())&&state.writingDesk===ownedRoot&&state.writingDesk?.currentId===current;
 const live=el=>owned()&&root.contains(el);
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};
 const status=(message,focus=false)=>{const el=root.querySelector('#writing-status');if(el){el.textContent=message;if(focus)el.focus();}};
 const persistence=()=>{const saved=ctx.save?.();return saved?.enabled===false?'This draft is in this session. Download Notes before leaving.':saved?.ok===false?'This draft is in this session but could not be saved on this device. Download Notes.':'';};
 const panels=()=>{v.panels=[...root.querySelectorAll('details[data-writing-panel][open]')].map(d=>d.dataset.writingPanel);};
 const redraw=(message='',focus='')=>{panels();stop();ctx.render?.();const next=document.querySelector('[data-writing-root]');if(next){const el=next.querySelector('#writing-status');if(el)el.textContent=message;const target=focus&&(Array.isArray(focus)?focus:[focus]).map(x=>next.querySelector(x)).find(Boolean);if(target){target.focus();if(target.getBoundingClientRect().top<0||target.getBoundingClientRect().bottom>innerHeight)target.scrollIntoView({block:'center'});}}};
 const options={canExport:ctx.canExport};
 const act=(el,fn,message='',focus='')=>{if(!live(el))return;const result=fn();if(!result.ok){status(errors[result.error]||errors.unavailable,true);return;}ownedRoot=state.writingDesk;const saved=result.changed===false?'':persistence();redraw([message,saved].filter(Boolean).join(' '),focus);};
 root.querySelectorAll('[data-writing-open]').forEach(el=>el.addEventListener('click',()=>{if(!live(el))return;act(el,()=>core.openWritingTask(state,el.dataset.writingOpen,options),'Your draft is waiting.','#writing-task-title');}));
 root.querySelectorAll('[data-writing-bench]').forEach(el=>el.addEventListener('click',()=>{if(!live(el))return;v.bench=el.dataset.writingBench;redraw('',`[data-writing-bench='${v.bench}']`);}));
 root.querySelectorAll('[data-writing-strip]').forEach(el=>el.addEventListener('click',()=>{if(!live(el))return;v.selected=el.dataset.writingStrip;redraw('','#writing-move-tools');}));
 root.querySelectorAll('[data-writing-destination]').forEach(el=>el.addEventListener('click',()=>{const key=v.selected;if(!key)return;act(el,()=>core.setWritingMaterial(state,{strip:key,heading:el.dataset.writingDestination},options),'The strip moved.',`[data-writing-strip='${key}']`);}));
 root.querySelectorAll('[data-writing-move]').forEach(el=>el.addEventListener('click',()=>{const id=el.dataset.writingMove,d=Number(el.dataset.writingDirection);act(el,()=>core.setWritingMaterial(state,{part:id,direction:d},options),'Paragraph moved.',[`[data-writing-move='${id}'][data-writing-direction='${d}']:not(:disabled)`,`[data-writing-move='${id}']:not(:disabled)`]);}));
 root.querySelectorAll('[data-writing-boundary]').forEach(el=>el.addEventListener('click',()=>{const id=el.dataset.writingBoundary,r=core.writingView(state).record;act(el,()=>core.setWritingMaterial(state,{boundary:r?.work.boundary===id?null:id},options),'Paragraph break changed.',`[data-writing-boundary='${id}']`);}));
 root.querySelectorAll('[data-writing-choice]').forEach(el=>el.addEventListener('click',()=>{const id=el.dataset.writingChoice;act(el,()=>core.setWritingMaterial(state,{choice:id},options),'Choice kept in your draft.',`[data-writing-choice='${id}']`);}));
 root.querySelectorAll('[data-writing-action]').forEach(el=>el.addEventListener('click',()=>{
  if(!live(el))return;const action=el.dataset.writingAction;
  if(action==='start')return act(el,()=>core.openWritingTask(state,'bakery',options),'','#writing-task-title');
  if(action==='check')return act(el,()=>core.checkWritingTask(state,options),'','#writing-feedback');
  if(action==='keep')return act(el,()=>core.keepWritingTask(state,options),'This version is in your notebook.','#writing-status');
  if(action==='next'){return act(el,()=>core.nextWritingTask(state,options),'Your earlier draft is waiting.','#writing-task-title');}
  if(action==='put-back')return act(el,()=>core.setWritingMaterial(state,{strip:v.selected,heading:null},options),'The strip is waiting again.',`[data-writing-strip='${v.selected}']`);
  if(['hint','example','together'].includes(action))return act(el,()=>core.showWritingHelp(state,action,options),'',`[data-writing-action='${action}']`);
 }));
 root.addEventListener('click',event=>{
  const el=event.target.closest('[data-speak]');if(!el||!root.contains(el))return;
  if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}
  if(core.writingView(state).record){const result=core.showWritingHelp(state,'narration',options);if(!result.ok){event.preventDefault();event.stopImmediatePropagation();status(errors[result.error]||errors.unavailable,true);return;}ownedRoot=state.writingDesk;if(result.changed!==false){const message=persistence();if(message)status(message);}}
  el.dataset.speak=[...root.querySelectorAll('[data-writing-read]')].filter(n=>n.closest('.wt-work,.wt-reader,.wt-arrival,[data-writing-panel=teaching],[data-writing-panel=help]')&&!n.closest('details:not([open]),[hidden]')&&n.getClientRects().length>0).map(n=>n.textContent.trim()).join(' ');
 },{capture:true});
 root.querySelectorAll('a').forEach(el=>el.addEventListener('click',e=>{if(!live(el))e.preventDefault();else stop();}));
}
